import type { EntityKind, ResourceKind } from "../sim/types";

export interface UnitDef {
  maxHp: number;
  speed: number; // tiles per tick
  gatherPerTick: number;
  carryCapacity: number;
  trainTicks: number;
  cost: Partial<Record<ResourceKind, number>>;
  pop: number;
}

export interface BuildingDef {
  maxHp: number;
  radius: number; // footprint radius in tiles
  buildTicks: number;
  cost: Partial<Record<ResourceKind, number>>;
  popProvided: number;
  canTrain: EntityKind[];
}

export interface ResourceNodeDef {
  resource: ResourceKind;
  amount: number;
  radius: number;
}

export const UNIT_DEFS: Record<string, UnitDef> = {
  villager: {
    maxHp: 25,
    speed: 0.08,
    gatherPerTick: 0.35,
    carryCapacity: 10,
    trainTicks: 50,
    cost: { food: 50 },
    pop: 1,
  },
};

export const BUILDING_DEFS: Record<string, BuildingDef> = {
  town_center: {
    maxHp: 2000,
    radius: 2.0,
    buildTicks: 0,
    cost: {},
    popProvided: 5,
    canTrain: ["villager"],
  },
  house: {
    maxHp: 400,
    radius: 0.8,
    buildTicks: 40,
    cost: { wood: 30 },
    popProvided: 5,
    canTrain: [],
  },
};

export const NODE_DEFS: Record<string, ResourceNodeDef> = {
  tree: { resource: "wood", amount: 100, radius: 0.45 },
  bush: { resource: "food", amount: 125, radius: 0.4 },
  gold_mine: { resource: "gold", amount: 200, radius: 0.55 },
  stone_mine: { resource: "stone", amount: 150, radius: 0.55 },
};

export function unitDef(kind: EntityKind): UnitDef | undefined {
  return UNIT_DEFS[kind];
}
export function buildingDef(kind: EntityKind): BuildingDef | undefined {
  return BUILDING_DEFS[kind];
}
export function nodeDef(kind: EntityKind): ResourceNodeDef | undefined {
  return NODE_DEFS[kind];
}
