import { NODE_DEFS, BUILDING_DEFS } from "./data/defs";
import type { Entity, GameState } from "./sim/types";

export interface Camera {
  x: number; // world coord at top-left, in tiles
  y: number;
  tileSize: number; // px per tile
}

export function renderFrame(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  cam: Camera,
  selection: Set<number>,
  hoverNodeId: number | null,
  canvasW: number,
  canvasH: number,
): void {
  ctx.fillStyle = "#2b3a1e";
  ctx.fillRect(0, 0, canvasW, canvasH);

  // Grid
  ctx.strokeStyle = "rgba(255,255,255,0.04)";
  ctx.lineWidth = 1;
  const startX = Math.floor(cam.x);
  const endX = Math.ceil(cam.x + canvasW / cam.tileSize);
  const startY = Math.floor(cam.y);
  const endY = Math.ceil(cam.y + canvasH / cam.tileSize);
  for (let x = startX; x <= endX; x++) {
    const sx = (x - cam.x) * cam.tileSize;
    ctx.beginPath();
    ctx.moveTo(sx, 0);
    ctx.lineTo(sx, canvasH);
    ctx.stroke();
  }
  for (let y = startY; y <= endY; y++) {
    const sy = (y - cam.y) * cam.tileSize;
    ctx.beginPath();
    ctx.moveTo(0, sy);
    ctx.lineTo(canvasW, sy);
    ctx.stroke();
  }

  // Draw resources first, then buildings, then villagers
  const layers: Entity[][] = [[], [], []];
  for (const e of state.entities.values()) {
    if (e.resource) layers[0].push(e);
    else if (e.kind === "villager") layers[2].push(e);
    else layers[1].push(e);
  }

  for (const e of layers[0]) drawNode(ctx, e, cam, hoverNodeId === e.id);
  for (const e of layers[1]) drawBuilding(ctx, e, cam, selection.has(e.id));
  for (const e of layers[2]) drawVillager(ctx, e, cam, selection.has(e.id));
}

function worldToScreen(cam: Camera, x: number, y: number): [number, number] {
  return [(x - cam.x) * cam.tileSize, (y - cam.y) * cam.tileSize];
}

function drawNode(ctx: CanvasRenderingContext2D, e: Entity, cam: Camera, hovered: boolean): void {
  if (!e.resource) return;
  const def = NODE_DEFS[e.kind];
  if (!def) return;
  const [sx, sy] = worldToScreen(cam, e.x, e.y);
  const r = def.radius * cam.tileSize;
  const colors: Record<string, string> = {
    tree: "#2e6b2e",
    bush: "#b44a5a",
    gold_mine: "#d9a93a",
    stone_mine: "#9aa0a6",
  };
  ctx.fillStyle = colors[e.kind] ?? "#888";
  ctx.beginPath();
  ctx.arc(sx, sy, r, 0, Math.PI * 2);
  ctx.fill();
  if (hovered) {
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  // Remaining bar for partially depleted
  const full = def.amount;
  if (e.resource.remaining < full) {
    const pct = e.resource.remaining / full;
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(sx - 10, sy - r - 6, 20, 3);
    ctx.fillStyle = "#8dd48d";
    ctx.fillRect(sx - 10, sy - r - 6, 20 * pct, 3);
  }
}

function drawBuilding(ctx: CanvasRenderingContext2D, e: Entity, cam: Camera, selected: boolean): void {
  const def = BUILDING_DEFS[e.kind];
  if (!def) return;
  const [sx, sy] = worldToScreen(cam, e.x, e.y);
  const r = def.radius * cam.tileSize;
  const isSite = !!e.site;
  const colors: Record<string, string> = {
    town_center: "#8a6a3c",
    house: "#6a4a2a",
  };
  ctx.fillStyle = isSite ? "rgba(200,200,200,0.35)" : colors[e.kind] ?? "#555";
  ctx.fillRect(sx - r, sy - r, r * 2, r * 2);
  ctx.strokeStyle = selected ? "#ffd27f" : "#000";
  ctx.lineWidth = selected ? 2 : 1;
  ctx.strokeRect(sx - r, sy - r, r * 2, r * 2);
  // Construction progress bar
  if (isSite && e.site) {
    const pct = e.site.built / e.site.required;
    ctx.fillStyle = "rgba(0,0,0,0.6)";
    ctx.fillRect(sx - r, sy - r - 6, r * 2, 4);
    ctx.fillStyle = "#7ab7ff";
    ctx.fillRect(sx - r, sy - r - 6, r * 2 * pct, 4);
  }
  // Training progress
  if (e.training) {
    const pct = e.training.progressTicks / e.training.requiredTicks;
    ctx.fillStyle = "rgba(0,0,0,0.6)";
    ctx.fillRect(sx - r, sy + r + 2, r * 2, 4);
    ctx.fillStyle = "#ffd27f";
    ctx.fillRect(sx - r, sy + r + 2, r * 2 * pct, 4);
  }
}

function drawVillager(ctx: CanvasRenderingContext2D, e: Entity, cam: Camera, selected: boolean): void {
  const [sx, sy] = worldToScreen(cam, e.x, e.y);
  const r = 0.3 * cam.tileSize;
  ctx.fillStyle = "#f1d6a1";
  ctx.beginPath();
  ctx.arc(sx, sy, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = selected ? "#ffd27f" : "#1a1a1a";
  ctx.lineWidth = selected ? 2 : 1;
  ctx.stroke();
  // Carry indicator
  if (e.carry && e.carry.amount > 0) {
    const carryColors: Record<string, string> = {
      food: "#d4b36a",
      wood: "#8b5a2b",
      gold: "#ffd84d",
      stone: "#bbbbbb",
    };
    ctx.fillStyle = carryColors[e.carry.resource] ?? "#fff";
    ctx.beginPath();
    ctx.arc(sx + r * 0.8, sy - r * 0.8, r * 0.45, 0, Math.PI * 2);
    ctx.fill();
  }
}
