import type { Camera } from "./render";
import type { Command, CommandKind, GameState } from "./sim/types";

export interface InputState {
  selection: Set<number>;
  buildGhost: { kind: "house" } | null;
  hoverNodeId: number | null;
}

export function createInputHandlers(
  canvas: HTMLCanvasElement,
  getState: () => GameState,
  getCam: () => Camera,
  getInput: () => InputState,
  setInput: (next: InputState) => void,
  enqueue: (cmd: CommandKind) => void,
): { dispose: () => void } {
  const screenToWorld = (sx: number, sy: number): [number, number] => {
    const cam = getCam();
    const rect = canvas.getBoundingClientRect();
    const cx = sx - rect.left;
    const cy = sy - rect.top;
    return [cam.x + cx / cam.tileSize, cam.y + cy / cam.tileSize];
  };

  const onMouseDown = (ev: MouseEvent) => {
    const state = getState();
    const input = getInput();
    const [wx, wy] = screenToWorld(ev.clientX, ev.clientY);

    if (ev.button === 0) {
      // Build placement
      if (input.buildGhost) {
        const ids = Array.from(input.selection).filter((id) => state.entities.get(id)?.kind === "villager");
        if (ids.length > 0) {
          enqueue({ type: "build_site", entityIds: ids, kind: "house", x: wx, y: wy });
        }
        setInput({ ...input, buildGhost: null });
        return;
      }
      // Selection — prefer villagers, then buildings
      const hit = pickEntity(state, wx, wy);
      const sel = new Set<number>();
      if (hit) sel.add(hit.id);
      setInput({ ...input, selection: sel });
    } else if (ev.button === 2) {
      // Right-click = command selected units
      const sel = Array.from(input.selection);
      if (sel.length === 0) return;
      const nodeHit = pickResourceNode(state, wx, wy);
      const villagerIds = sel.filter((id) => state.entities.get(id)?.kind === "villager");
      if (nodeHit && villagerIds.length > 0) {
        enqueue({ type: "gather", entityIds: villagerIds, nodeId: nodeHit.id });
      } else if (villagerIds.length > 0) {
        enqueue({ type: "move", entityIds: villagerIds, x: wx, y: wy });
      }
    }
  };

  const onMouseMove = (ev: MouseEvent) => {
    const state = getState();
    const [wx, wy] = screenToWorld(ev.clientX, ev.clientY);
    const node = pickResourceNode(state, wx, wy);
    const input = getInput();
    if ((node?.id ?? null) !== input.hoverNodeId) {
      setInput({ ...input, hoverNodeId: node?.id ?? null });
    }
  };

  const onContextMenu = (ev: MouseEvent) => ev.preventDefault();

  canvas.addEventListener("mousedown", onMouseDown);
  canvas.addEventListener("mousemove", onMouseMove);
  canvas.addEventListener("contextmenu", onContextMenu);

  return {
    dispose: () => {
      canvas.removeEventListener("mousedown", onMouseDown);
      canvas.removeEventListener("mousemove", onMouseMove);
      canvas.removeEventListener("contextmenu", onContextMenu);
    },
  };
}

function pickEntity(state: GameState, wx: number, wy: number) {
  let best: { id: number; kind: string; d: number } | null = null;
  for (const e of state.entities.values()) {
    if (e.owner !== 0) continue;
    const r = e.kind === "villager" ? 0.4 : 1.6;
    const dx = e.x - wx;
    const dy = e.y - wy;
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d <= r && (!best || d < best.d || (best.kind !== "villager" && e.kind === "villager"))) {
      best = { id: e.id, kind: e.kind, d };
    }
  }
  if (!best) return null;
  return state.entities.get(best.id);
}

function pickResourceNode(state: GameState, wx: number, wy: number) {
  for (const e of state.entities.values()) {
    if (!e.resource) continue;
    const dx = e.x - wx;
    const dy = e.y - wy;
    if (dx * dx + dy * dy <= 0.6 * 0.6) return e;
  }
  return null;
}

// Unused helper kept for symmetry with Command type
export type { Command };
