import { RNG } from "./rng";
import { BUILDING_DEFS, NODE_DEFS, UNIT_DEFS } from "../data/defs";
import type { Entity, EntityKind, GameState } from "./types";

export const MAP_W = 60;
export const MAP_H = 40;

export function createWorld(seed: number): GameState {
  const state: GameState = {
    tick: 0,
    seed,
    rngState: seed >>> 0,
    entities: new Map(),
    nextEntityId: 1,
    players: [
      { resources: { food: 200, wood: 200, gold: 100, stone: 100 }, pop: 0, popCap: 0, autoGather: true },
    ],
    mapW: MAP_W,
    mapH: MAP_H,
  };
  const rng = new RNG(seed);

  // Town Center near center-left
  const tcX = 10;
  const tcY = 20;
  spawnBuilding(state, "town_center", tcX, tcY, 0, /*built*/ true);

  // 3 starting villagers
  for (let i = 0; i < 3; i++) {
    spawnUnit(state, "villager", tcX + 2 + i * 0.6, tcY + 2, 0);
  }

  // Scatter trees (forest cluster)
  for (let i = 0; i < 40; i++) {
    const x = rng.range(14, 22) + rng.range(-1, 1);
    const y = rng.range(14, 26) + rng.range(-1, 1);
    spawnNode(state, "tree", x, y);
  }
  // Berry bushes
  for (let i = 0; i < 6; i++) {
    spawnNode(state, "bush", 7 + i * 0.9, 24 + rng.range(-0.2, 0.2));
  }
  // Gold mines
  for (let i = 0; i < 4; i++) {
    spawnNode(state, "gold_mine", 28 + rng.range(-0.5, 0.5), 10 + i * 1.2);
  }
  // Stone mines
  for (let i = 0; i < 4; i++) {
    spawnNode(state, "stone_mine", 30 + rng.range(-0.5, 0.5), 30 + i * 1.2);
  }

  state.rngState = rng.getState();
  recomputePop(state);
  return state;
}

export function spawnUnit(state: GameState, kind: EntityKind, x: number, y: number, owner: number): Entity {
  const def = UNIT_DEFS[kind];
  if (!def) throw new Error(`unit def missing: ${kind}`);
  const e: Entity = {
    id: state.nextEntityId++,
    kind,
    owner,
    x,
    y,
    hp: def.maxHp,
    maxHp: def.maxHp,
    task: { type: "idle" },
  };
  state.entities.set(e.id, e);
  return e;
}

export function spawnBuilding(
  state: GameState,
  kind: EntityKind,
  x: number,
  y: number,
  owner: number,
  built: boolean,
): Entity {
  const def = BUILDING_DEFS[kind];
  if (!def) throw new Error(`building def missing: ${kind}`);
  const e: Entity = {
    id: state.nextEntityId++,
    kind,
    owner,
    x,
    y,
    hp: built ? def.maxHp : 1,
    maxHp: def.maxHp,
    training: null,
  };
  if (!built) {
    e.site = { kind, built: 0, required: def.buildTicks };
  }
  state.entities.set(e.id, e);
  return e;
}

export function spawnNode(state: GameState, kind: EntityKind, x: number, y: number): Entity {
  const def = NODE_DEFS[kind];
  if (!def) throw new Error(`node def missing: ${kind}`);
  const e: Entity = {
    id: state.nextEntityId++,
    kind,
    owner: 1,
    x,
    y,
    hp: 1,
    maxHp: 1,
    resource: { kind: def.resource, remaining: def.amount },
  };
  state.entities.set(e.id, e);
  return e;
}

export function recomputePop(state: GameState): void {
  for (let p = 0; p < state.players.length; p++) {
    let pop = 0;
    let cap = 0;
    for (const e of state.entities.values()) {
      if (e.owner !== p) continue;
      if (e.kind === "villager") pop += 1;
      if (e.site) continue; // unfinished buildings don't grant pop
      if (e.kind === "town_center") cap += BUILDING_DEFS.town_center.popProvided;
      if (e.kind === "house") cap += BUILDING_DEFS.house.popProvided;
    }
    state.players[p].pop = pop;
    state.players[p].popCap = Math.min(cap, 200);
  }
}
