import { createWorld } from "./sim/world";
import { TICKS_PER_SECOND, tick } from "./sim/tick";
import type { Command, CommandKind, GameState } from "./sim/types";
import { renderFrame, type Camera } from "./render";
import { createInputHandlers, type InputState } from "./input";

const canvas = document.getElementById("game") as HTMLCanvasElement;
const ctx = canvas.getContext("2d")!;

let state: GameState = createWorld(42);
const cam: Camera = { x: 2, y: 8, tileSize: 32 };
let input: InputState = { selection: new Set<number>(), buildGhost: null, hoverNodeId: null };

// Command queue (input-delayed by 1 tick to keep sim deterministic for future netcode)
const pending: Command[] = [];
function enqueue(cmd: CommandKind): void {
  pending.push({ tick: state.tick + 1, cmd });
}

function resize(): void {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

// Keyboard pan + hotkeys
const keys = new Set<string>();
window.addEventListener("keydown", (e) => {
  keys.add(e.key.toLowerCase());
  if (e.key.toLowerCase() === "b") {
    input = { ...input, buildGhost: { kind: "house" } };
  } else if (e.key === "Escape") {
    input = { ...input, buildGhost: null, selection: new Set() };
  }
});
window.addEventListener("keyup", (e) => keys.delete(e.key.toLowerCase()));

createInputHandlers(
  canvas,
  () => state,
  () => cam,
  () => input,
  (next) => { input = next; },
  enqueue,
);

// HUD wiring
const elFood = document.getElementById("r-food")!;
const elWood = document.getElementById("r-wood")!;
const elGold = document.getElementById("r-gold")!;
const elStone = document.getElementById("r-stone")!;
const elPop = document.getElementById("r-pop")!;
const elTick = document.getElementById("tick")!;
const elSel = document.getElementById("selection")!;
const btnTrain = document.getElementById("btn-train-villager") as HTMLButtonElement;
const btnHouse = document.getElementById("btn-build-house") as HTMLButtonElement;
const btnAuto = document.getElementById("btn-toggle-autogather") as HTMLButtonElement;

btnTrain.addEventListener("click", () => {
  const tc = [...state.entities.values()].find((e) => e.kind === "town_center" && e.owner === 0 && !e.site);
  if (!tc) return;
  enqueue({ type: "train", buildingId: tc.id, kind: "villager" });
});
btnHouse.addEventListener("click", () => {
  input = { ...input, buildGhost: { kind: "house" } };
});
btnAuto.addEventListener("click", () => {
  enqueue({ type: "toggle_autogather" });
});

// Fixed-timestep sim
const tickMs = 1000 / TICKS_PER_SECOND;
let acc = 0;
let last = performance.now();

function loop(now: number): void {
  const dt = now - last;
  last = now;
  acc += dt;

  // Camera pan (not part of sim)
  const panSpeed = 12 / cam.tileSize;
  if (keys.has("arrowleft") || keys.has("a")) cam.x -= panSpeed;
  if (keys.has("arrowright") || keys.has("d")) cam.x += panSpeed;
  if (keys.has("arrowup") || keys.has("w")) cam.y -= panSpeed;
  if (keys.has("arrowdown") || keys.has("s")) cam.y += panSpeed;
  cam.x = Math.max(-4, Math.min(state.mapW - 4, cam.x));
  cam.y = Math.max(-4, Math.min(state.mapH - 4, cam.y));

  // Drain all ready commands, tick sim forward
  let safety = 5;
  while (acc >= tickMs && safety-- > 0) {
    const ready = pending.filter((c) => c.tick <= state.tick);
    for (let i = pending.length - 1; i >= 0; i--) if (pending[i].tick <= state.tick) pending.splice(i, 1);
    tick(state, ready);
    acc -= tickMs;
  }

  // HUD update
  const p = state.players[0];
  elFood.textContent = Math.floor(p.resources.food).toString();
  elWood.textContent = Math.floor(p.resources.wood).toString();
  elGold.textContent = Math.floor(p.resources.gold).toString();
  elStone.textContent = Math.floor(p.resources.stone).toString();
  elPop.textContent = `${p.pop}/${p.popCap}`;
  elTick.textContent = `tick ${state.tick}`;
  btnAuto.textContent = `Auto-Gather: ${p.autoGather ? "ON" : "OFF"}`;
  btnTrain.disabled = p.resources.food < 50 || p.pop >= p.popCap;
  btnHouse.disabled = p.resources.wood < 30;

  // Selection readout
  if (input.selection.size === 0) {
    elSel.textContent = input.buildGhost
      ? "Placing: House (left-click to place, Esc to cancel)"
      : "No selection — left-click a villager. Right-click a resource to gather. B = build house.";
  } else {
    const parts: string[] = [];
    for (const id of input.selection) {
      const e = state.entities.get(id);
      if (!e) continue;
      if (e.kind === "villager") {
        const t = e.task;
        const taskStr = !t || t.type === "idle" ? "idle" : t.type;
        const carry = e.carry && e.carry.amount > 0 ? ` [${e.carry.resource} ${e.carry.amount.toFixed(1)}]` : "";
        parts.push(`Villager #${e.id} (${taskStr})${carry}`);
      } else {
        const tr = e.training ? ` training ${e.training.kind} ${Math.floor((e.training.progressTicks / e.training.requiredTicks) * 100)}%` : "";
        parts.push(`${e.kind} #${e.id}${tr}`);
      }
    }
    elSel.textContent = parts.join(" | ");
  }

  // Render
  renderFrame(ctx, state, cam, input.selection, input.hoverNodeId, canvas.width, canvas.height);

  // Build ghost preview
  if (input.buildGhost) {
    // Draw at last mouse position — use HUD hint only for now
    ctx.strokeStyle = "rgba(255,210,127,0.8)";
    ctx.setLineDash([6, 4]);
    ctx.strokeRect(10, canvas.height - 60, 200, 24);
    ctx.setLineDash([]);
  }

  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
