import { RNG } from "./rng";
import { BUILDING_DEFS, NODE_DEFS, UNIT_DEFS } from "../data/defs";
import { recomputePop, spawnBuilding, spawnUnit } from "./world";
import type { Command, CommandKind, Entity, EntityKind, GameState, ResourceKind } from "./types";

export const TICKS_PER_SECOND = 20;

export function tick(state: GameState, commandsThisTick: Command[]): void {
  for (const c of commandsThisTick) applyCommand(state, c.cmd);

  const rng = new RNG(0);
  rng.setState(state.rngState);

  // Systems — order matters for determinism
  systemTraining(state);
  systemBuildSites(state);
  systemMovement(state);
  systemGather(state, rng);
  systemAutoRetask(state);

  state.rngState = rng.getState();
  state.tick += 1;
  recomputePop(state);
}

function applyCommand(state: GameState, cmd: CommandKind): void {
  switch (cmd.type) {
    case "move": {
      for (const id of cmd.entityIds) {
        const e = state.entities.get(id);
        if (!e || e.kind !== "villager") continue;
        e.task = { type: "move", tx: cmd.x, ty: cmd.y };
      }
      break;
    }
    case "gather": {
      const node = state.entities.get(cmd.nodeId);
      if (!node || !node.resource) break;
      for (const id of cmd.entityIds) {
        const e = state.entities.get(id);
        if (!e || e.kind !== "villager") continue;
        e.task = { type: "gather", nodeId: cmd.nodeId, resource: node.resource.kind, returning: false };
        e.lastResourceNodeId = cmd.nodeId;
        e.lastResourceKind = node.resource.kind;
      }
      break;
    }
    case "build_site": {
      const bdef = BUILDING_DEFS[cmd.kind];
      if (!bdef) break;
      const p = state.players[0];
      if (!canAfford(p.resources, bdef.cost)) break;
      pay(p.resources, bdef.cost);
      const site = spawnBuilding(state, cmd.kind, cmd.x, cmd.y, 0, false);
      for (const id of cmd.entityIds) {
        const e = state.entities.get(id);
        if (!e || e.kind !== "villager") continue;
        e.task = { type: "build", siteId: site.id };
      }
      break;
    }
    case "train": {
      const b = state.entities.get(cmd.buildingId);
      if (!b || b.site) break;
      const bdef = BUILDING_DEFS[b.kind];
      if (!bdef || !bdef.canTrain.includes(cmd.kind)) break;
      if (b.training) break;
      const udef = UNIT_DEFS[cmd.kind];
      if (!udef) break;
      const p = state.players[0];
      if (p.pop >= p.popCap) break;
      if (!canAfford(p.resources, udef.cost)) break;
      pay(p.resources, udef.cost);
      b.training = { kind: cmd.kind, progressTicks: 0, requiredTicks: udef.trainTicks };
      break;
    }
    case "toggle_autogather": {
      state.players[0].autoGather = !state.players[0].autoGather;
      break;
    }
  }
}

function canAfford(r: GameState["players"][number]["resources"], cost: Partial<Record<ResourceKind, number>>): boolean {
  return (!cost.food || r.food >= cost.food)
    && (!cost.wood || r.wood >= cost.wood)
    && (!cost.gold || r.gold >= cost.gold)
    && (!cost.stone || r.stone >= cost.stone);
}
function pay(r: GameState["players"][number]["resources"], cost: Partial<Record<ResourceKind, number>>): void {
  if (cost.food) r.food -= cost.food;
  if (cost.wood) r.wood -= cost.wood;
  if (cost.gold) r.gold -= cost.gold;
  if (cost.stone) r.stone -= cost.stone;
}

function systemTraining(state: GameState): void {
  for (const e of state.entities.values()) {
    if (!e.training) continue;
    if (e.site) continue;
    e.training.progressTicks += 1;
    if (e.training.progressTicks >= e.training.requiredTicks) {
      const p = state.players[0];
      if (p.pop < p.popCap) {
        // Spawn next to building
        spawnUnit(state, e.training.kind, e.x + 1.2, e.y + 1.2, e.owner);
      }
      e.training = null;
    }
  }
}

function systemBuildSites(state: GameState): void {
  const builders: Map<number, number> = new Map();
  for (const e of state.entities.values()) {
    if (e.kind !== "villager" || !e.task || e.task.type !== "build") continue;
    const site = state.entities.get(e.task.siteId);
    if (!site || !site.site) {
      e.task = { type: "idle" };
      continue;
    }
    const d = dist(e, site);
    if (d > 1.2) {
      // Walk to site
      const step = UNIT_DEFS.villager.speed;
      stepToward(e, site.x, site.y, step);
    } else {
      builders.set(site.id, (builders.get(site.id) ?? 0) + 1);
    }
  }
  for (const [siteId, n] of builders) {
    const site = state.entities.get(siteId);
    if (!site || !site.site) continue;
    site.site.built += n;
    site.hp = Math.min(site.maxHp, Math.round((site.site.built / site.site.required) * site.maxHp));
    if (site.site.built >= site.site.required) {
      site.hp = site.maxHp;
      delete site.site;
      // Free up builders
      for (const e of state.entities.values()) {
        if (e.task && e.task.type === "build" && e.task.siteId === siteId) {
          e.task = { type: "idle" };
        }
      }
    }
  }
}

function systemMovement(state: GameState): void {
  const speed = UNIT_DEFS.villager.speed;
  for (const e of state.entities.values()) {
    if (e.kind !== "villager" || !e.task) continue;
    if (e.task.type === "move") {
      const arrived = stepToward(e, e.task.tx, e.task.ty, speed);
      if (arrived) e.task = { type: "idle" };
    }
  }
}

function systemGather(state: GameState, _rng: RNG): void {
  const def = UNIT_DEFS.villager;
  const tc = findTownCenter(state, 0);
  for (const e of state.entities.values()) {
    if (e.kind !== "villager" || !e.task || e.task.type !== "gather") continue;
    const node = state.entities.get(e.task.nodeId);

    if (e.task.returning) {
      // Walk back to TC to deposit
      if (!tc) { e.task = { type: "idle" }; continue; }
      const arrived = stepToward(e, tc.x, tc.y, def.speed);
      if (arrived) {
        if (e.carry) {
          deposit(state, e.carry.resource, e.carry.amount, 0);
          e.carry = undefined;
        }
        // Go back to node or find replacement
        const next = node && node.resource && node.resource.remaining > 0
          ? node
          : findNearestResourceOfKind(state, e, e.task.resource);
        if (next && next.resource) {
          e.task = { type: "gather", nodeId: next.id, resource: next.resource.kind, returning: false };
          e.lastResourceNodeId = next.id;
          e.lastResourceKind = next.resource.kind;
        } else {
          e.task = { type: "idle" };
        }
      }
      continue;
    }

    // Outbound — walk to node, then gather
    if (!node || !node.resource || node.resource.remaining <= 0) {
      const next = findNearestResourceOfKind(state, e, e.task.resource);
      if (next && next.resource) {
        e.task = { type: "gather", nodeId: next.id, resource: next.resource.kind, returning: false };
        e.lastResourceNodeId = next.id;
        e.lastResourceKind = next.resource.kind;
      } else {
        // Return with whatever we have
        e.task = { type: "gather", nodeId: e.task.nodeId, resource: e.task.resource, returning: true };
      }
      continue;
    }

    const ndef = NODE_DEFS[node.kind];
    const gatherRange = (ndef?.radius ?? 0.5) + 0.6;
    if (dist(e, node) > gatherRange) {
      stepToward(e, node.x, node.y, def.speed);
      continue;
    }
    // Gather
    if (!e.carry) e.carry = { resource: node.resource.kind, amount: 0 };
    const take = Math.min(def.gatherPerTick, node.resource.remaining, def.carryCapacity - e.carry.amount);
    e.carry.amount += take;
    node.resource.remaining -= take;
    if (e.carry.amount >= def.carryCapacity) {
      e.task = { type: "gather", nodeId: node.id, resource: node.resource.kind, returning: true };
    } else if (node.resource.remaining <= 0) {
      // Node exhausted — despawn
      state.entities.delete(node.id);
      if (e.carry.amount > 0) {
        e.task = { type: "gather", nodeId: node.id, resource: e.carry.resource, returning: true };
      } else {
        const next = findNearestResourceOfKind(state, e, e.task.resource);
        if (next && next.resource) {
          e.task = { type: "gather", nodeId: next.id, resource: next.resource.kind, returning: false };
        } else {
          e.task = { type: "idle" };
        }
      }
    }
  }
}

// Idle villagers resume their last resource if auto-gather is on.
function systemAutoRetask(state: GameState): void {
  if (!state.players[0].autoGather) return;
  for (const e of state.entities.values()) {
    if (e.kind !== "villager" || !e.task || e.task.type !== "idle") continue;
    if (e.lastResourceKind === undefined) continue;
    const next = findNearestResourceOfKind(state, e, e.lastResourceKind);
    if (next && next.resource) {
      e.task = { type: "gather", nodeId: next.id, resource: next.resource.kind, returning: false };
      e.lastResourceNodeId = next.id;
    }
  }
}

function deposit(state: GameState, resource: ResourceKind, amount: number, player: number): void {
  const r = state.players[player].resources;
  r[resource] = Math.round((r[resource] + amount) * 100) / 100;
}

function findTownCenter(state: GameState, owner: number): Entity | undefined {
  for (const e of state.entities.values()) {
    if (e.kind === "town_center" && e.owner === owner && !e.site) return e;
  }
  return undefined;
}

function findNearestResourceOfKind(state: GameState, from: Entity, kind: ResourceKind): Entity | undefined {
  let best: Entity | undefined;
  let bestD = Infinity;
  for (const e of state.entities.values()) {
    if (!e.resource || e.resource.kind !== kind || e.resource.remaining <= 0) continue;
    const d = dist(from, e);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  return best;
}

function dist(a: { x: number; y: number }, b: { x: number; y: number }): number {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy);
}

function stepToward(e: Entity, tx: number, ty: number, step: number): boolean {
  const dx = tx - e.x;
  const dy = ty - e.y;
  const d = Math.sqrt(dx * dx + dy * dy);
  if (d <= step) {
    e.x = tx;
    e.y = ty;
    return true;
  }
  e.x += (dx / d) * step;
  e.y += (dy / d) * step;
  return false;
}

// Re-exports for callers who want to build node/unit kinds externally
export type { Entity, EntityKind, GameState, Command };
